function FR(n,w,h,bg){const f=figma.createFrame();f.name=n;f.resize(w,h);f.fills=bg?[{type:'SOLID',color:hx(bg)}]:[];return f;}
function RC(w,h,c,rad){const r=figma.createRectangle();r.resize(w,h);r.fills=[{type:'SOLID',color:hx(c)}];if(rad!==undefined)r.cornerRadius=rad;return r;}
function EL(w,h,c){const e=figma.createEllipse();e.resize(w,h);e.fills=[{type:'SOLID',color:hx(c)}];return e;}
function rec(n,c){n.findAll(x=>('fills'in x)&&Array.isArray(x.fills)&&x.fills.some(f=>f.type==='SOLID')).forEach(v=>v.fills=[{type:'SOLID',color:hx(c)}]);}
async function IC(id,cl){const i=(await figma.getNodeByIdAsync(id)).createInstance();if(cl)rec(i,cl);return i;}
async function SB(cl){return IC('1:33',cl||'#1F2B33');}
async function HI(cl){return IC('1:43',cl||'#1F2B33');}
function pos(n,x,y){n.x=x;n.y=y;return n;}
const B='#324A59',BG='#F7F4EF',CARD='#FFFFFF',SUB='#8A97A0',LINE='#EAE5DE',GRN='#3BA272',RED='#C25B4E';
