const dset=ws.children.find(n=>n.name==='Drink Card');
function frameAt(i,name,h){const f=FR(name,375,h||812,BG);ws.appendChild(f);f.x=((i-1)%4)*425;f.y=Math.floor((i-1)/4)*980;return f;}
async function header(title){const h=hdC.createInstance();h.name='Header · '+title;const tt=h.findOne(n=>n.type==='TEXT'&&n.characters==='Order');tt.characters=title;return h;}
async function tabbar(active){const t=tbC.createInstance();t.name='Tab Bar · '+active;const names=['Store','Rewards','Orders'];
for(const lb of t.findAll(n=>n.type==='TEXT')){lb.fills=[{type:'SOLID',color:hx(lb.characters===active?B:SUB)}];}
